    { id: "k58", title: "传感器技术", question: "请说明传感器在自动化系统中的重要作用，并列举几种常用传感器。", type: "专业", answer: ["传感器是自动化系统的感知元件，获取物理量信息", "温度传感器：热电偶、热电阻、红外温度传感器", "压力传感器：应变式、压电式、电容式压力传感器", "位移传感器：电位器式、电感式、光栅位移传感器", "传感器选型需考虑量程、精度、响应速度和环境适应性"] },
    { id: "k59", title: "PLC应用", question: "请简述PLC（可编程逻辑控制器）的基本工作原理和典型应用场景。", type: "专业", answer: ["PLC采用循环扫描工作方式：输入采样、程序执行、输出刷新", "梯形图是最常用的PLC编程语言，直观易学", "PLC具有高可靠性、抗干扰能力强、模块化设计的特点", "广泛应用于制造业自动化流水线、过程控制等领域", "现代PLC支持网络通信和远程监控功能"] },
    { id: "k60", title: "报考动机", question: "你为什么选择报考自动化专业研究生？", type: "综合", answer: ["阐述对自动化前沿领域的兴趣和认识", "介绍本科阶段的学习和实践经历", "说明对目标院校自动化学科的了解", "表达在特定方向的研究兴趣", "展望未来的学术或职业发展规划"] },
    { id: "k61", title: "研究规划", question: "如果被录取，研究生阶段有什么研究规划？", type: "综合", answer: ["系统学习专业核心课程和前沿知识", "积极参与导师的科研项目", "确定具体研究方向并开展系统研究", "争取发表学术论文", "明确毕业后的发展路径"] },
    { id: "k62", title: "英语口语", question: "Please describe the role of automation in modern manufacturing and your interest in this field.", type: "英语", answer: ["Explain the importance of automation in manufacturing", "Describe specific technologies like robotics, IoT, AI", "Share your personal interest in automation", "Discuss future trends and opportunities", "Speak clearly and fluently in English"] },
    { id: "k63", title: "政治素养", question: "请谈谈你对\"智能制造\"国家战略的理解，以及自动化专业如何助力智能制造。", type: "政治", answer: ["智能制造是制造强国战略的主攻方向", "自动化是实现智能制造的核心技术基础", "工业机器人、智能控制、数字孪生等关键技术", "自动化专业为智能制造提供人才和技术支撑", "将个人研究与智能制造发展需求相结合"] },
    { id: "k64", title: "现代控制", question: "请简述状态空间表示法与经典传递函数表示法的主要区别。", type: "专业", answer: ["传递函数描述输入输出关系，适用于单输入单输出系统", "状态空间描述系统内部状态，适用于多变量系统", "状态空间法可处理非线性系统和时变系统", "状态空间法便于计算机数值求解", "现代控制理论基于状态空间法，如最优控制、鲁棒控制"] },
    { id: "k65", title: "科研素养", question: "请谈谈你对研究生阶段从事控制理论研究的理解。", type: "综合", answer: ["控制理论研究需要扎实的数学基础", "理论与实际应用相结合非常重要", "关注控制理论前沿方向，如智能控制、自适应控制", "MATLAB/Simulink是重要的仿真工具", "注重培养独立思考和解决问题的能力"] }
