function getQuestions(scene, job) {
  var sceneData = QUESTION_BANK[scene];
  if (!sceneData) return [];
  var questions = sceneData[job];
  if (!questions || questions.length === 0) return [];
  var result = [];
  for (var qi = 0; qi < questions.length; qi++) {
    var q = questions[qi];
    var obj = {};
    for (var key in q) {
      if (q.hasOwnProperty(key)) {
        if (key === 'answer' && Array.isArray(q[key])) {
          obj[key] = q[key].join('；');
        } else {
          obj[key] = q[key];
        }
      }
    }
    obj.num = qi + 1;
    result.push(obj);
  }
  return result;
}

function getDefaultJob(scene, category) {
  var defaults = {
    job: {
      '技术研发': 'Java开发', '产品与设计': '产品经理', '市场与运营': '运营专员',
      '金融与咨询': '金融分析师', '医疗与健康': '临床医生', '制造与供应链': '生产主管'
    },
    kaoyan: {
      '理工类': '计算机科学', '文史类': '中国语言文学', '经管类': '工商管理',
      '法学类': '民商法', '教育类': '教育学', '医学类': '临床医学'
    },
    kaogong: {
      '国考': '综合管理', '省考': '省级机关', '事业编': '教育事业单位',
      '军队文职': '行政管理', '遴选': '省级遴选', '村官': '大学生村官'
    }
  };
  return (defaults[scene] && defaults[scene][category]) || 'Java开发';
}

module.exports = {
  getQuestions: getQuestions,
  getDefaultJob: getDefaultJob,
  QUESTION_BANK: QUESTION_BANK
};